  const x=176+col*34+row*8,y=111+row*30-col*2,sector=x<265?0:x>470?2:1,width=10+(col*7+row*3)%12,depth=width*.48,height=(row<4&&col>2&&col<8?42:12)+(col*13+row*17)%38;
