   if(r.ok){info.mapCommands++;ensureFeedback(action==='move'?'移動指令実行 / 予測射界を再評価':action==='guard'?'A.T.防御命令を発令':action==='mode'?'照準モードへ移行':'都市援護命令を更新');}
